import numpy as np

def solve_test(input_grid):
    input_grid = np.array(input_grid)
    rows, cols = input_grid.shape

    # Start by copying input
    output_grid = input_grid.copy()

    # Find all non-7 values as centers
    centers = []
    for r in range(rows):
        for c in range(cols):
            if input_grid[r, c] != 7:
                centers.append((r, c))

    # For each center, compute the diamond pattern of 5s
    for r_center, c_center in centers:
        for r in range(r_center, rows):
            row_offset = r - r_center

            if row_offset == 0:
                continue

            if row_offset % 2 == 1:  # odd offset
                pattern_col = c_center - row_offset + 1
                if 0 <= pattern_col < cols:
                    # Only turn 7s into 5s
                    if output_grid[r, pattern_col] == 7:
                        output_grid[r, pattern_col] = 5
            else:  # even offset
                left = c_center - row_offset
                for dc in [0, 1, 2]:
                    col = left + dc
                    if 0 <= col < cols:
                        if output_grid[r, col] == 7:
                            output_grid[r, col] = 5

    return output_grid.tolist()

def solve_demo_correct():
    center_r, center_c = 0, 6    
    output_grid = np.full((5, 9), 7, dtype=int)
    output_grid[0, 6] = 8

    for r in range(1, 5):
        d = r - center_r
        if d % 2 == 1:  # odd
            pattern_col = center_c - d + 1
            if 0 <= pattern_col < 9:
                output_grid[r, pattern_col] = 5
        else:  # even
            left = center_c - d
            if 0 <= left < 9:
                output_grid[r, left] = 5
                if left + 1 < 9:
                    output_grid[r, left + 1] = 5
                if left + 2 < 9:
                    output_grid[r, left + 2] = 5
    return output_grid

# Test with demo
print("Testing solve_test with demo:")
demo_input = [
    [7, 7, 7, 7, 7, 7, 8, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7],
    [7, 7, 7, 7, 7, 7, 7, 7, 7],
]
demo_expected = [
    [7, 7, 7, 7, 7, 7, 8, 7, 7],
    [7, 7, 7, 7, 7, 7, 5, 7, 7],
    [7, 7, 7, 7, 5, 5, 5, 7, 7],
    [7, 7, 7, 7, 5, 7, 7, 7, 7],
    [7, 7, 5, 5, 5, 7, 7, 7, 7],
]
result = solve_test(demo_input)
print("Result:")
for row in result:
    print(row)
print("\nExpected:")
for row in demo_expected:
    print(row)
print("\nMatch:", result == demo_expected)

# Also compute solve_demo_correct for comparison
dc = solve_demo_correct()
print("\n\nCorrect demo result:")
for row in dc:
    print(row)

